// Банк по мотивам сборника Сканави: текстовые задачи (глава 13), прогрессии,
// статистика и вероятность, координаты и векторы. Шаблоны параметрические:
// числа случайные, задача строится «от ответа», поэтому все величины целые
// или простые десятичные. Тексты на двух языках, ответ считается в коде.
import { lead, term, type Template } from '../helpers'
import { c, h, N, T as T0, pick, rnd, frac, gcd, signed, raz, type B } from './bi'

// Варианты без повторов: совпавшие заменяются соседними значениями верного ответа
const key = (x: B | string) => (typeof x === 'string' ? x : x[0])
const bump = (r: string, i: number) => (/\d/.test(r) ? r.replace(/\d+/, m => String(+m + i)) : r.replace('$', `$${i + 1}`))
const T = (q: B, right: B | string, wrongs: (B | string)[], n: number, sol: B | string) => {
  const seen = new Set([key(right)]), w: (B | string)[] = []
  for (const x of wrongs) if (!seen.has(key(x))) { seen.add(key(x)); w.push(x) }
  for (let i = 1; typeof right === 'string' && w.length < 4 && i < 40; i++) { const x = bump(right, i); if (!seen.has(x)) { seen.add(x); w.push(x) } }
  return T0(q, right, w, n, sol)
}
const Q = (ru: string, kk: string): B => [ru, kk]

// Десятичная дробь без округления: 2.5 → 2{,}5 (вне формул станет «2,5»)
const dz = (x: number) => String(+x.toFixed(6)).replace('.', '{,}')
// Отрицательное число в скобках: для подстановки в выражения
const pp = (x: number) => (x < 0 ? `(${x})` : String(x))
// Координаты: (1;\ -2;\ 3)
const vec = (...a: number[]) => `(${a.map(dz).join(';\\ ')})`
// Слагаемые уравнения без пустых мест: «x^2 + y^2 - 4x + 3 = 0»
const J = (...p: string[]) => p.filter(Boolean).join(' ')
// (x - a)^2, при a = 0 просто x^2
const sq = (v: string, a: number) => (a === 0 ? `${v}^2` : `(${v} ${signed(-a)})^2`)
// x + a, при a = 0 просто x
const lin = (v: string, a: number) => (a === 0 ? v : `${v} ${signed(a)}`)
// Множитель (x + a), при a = 0 просто x
const fac = (a: number) => (a === 0 ? 'x' : `(${lin('x', a)})`)
// Слагаемое со знаком, ноль тоже пишем: «+ 0», «- 3»
const add = (x: number) => (x < 0 ? `- ${-x}` : `+ ${x}`)
// Русское множественное число: 1 шар, 2 шара, 5 шаров
const pl = (k: number, one: string, few: string, many: string) => {
  const d = k % 10, t = k % 100
  return d === 1 && t !== 11 ? one : d >= 2 && d <= 4 && (t < 12 || t > 14) ? few : many
}
const lcm = (a: number, b: number) => (a / gcd(a, b)) * b
const sgn = () => pick([1, -1])
const nz = (lo: number, hi: number) => { let x = 0; while (x === 0) x = rnd(lo, hi); return x }
// Пифагоровы тройки и четвёрки (a² + b² + c² = d²)
const TR: [number, number, number][] = [[3, 4, 5], [6, 8, 10], [5, 12, 13], [8, 15, 17], [9, 12, 15]]
const TR3: [number, number, number, number][] = [[1, 2, 2, 3], [2, 3, 6, 7], [1, 4, 8, 9], [2, 6, 9, 11], [4, 4, 7, 9], [2, 10, 11, 15]]
// (R, d, r): R² = d² + r²
const RDR: [number, number, number][] = [[5, 3, 4], [5, 4, 3], [13, 5, 12], [13, 12, 5], [10, 6, 8], [10, 8, 6], [17, 8, 15], [17, 15, 8], [15, 9, 12]]
const PERM = [[0, 1, 2], [0, 2, 1], [1, 0, 2], [1, 2, 0], [2, 0, 1], [2, 1, 0]]
// Нормаль с целой длиной: перестановка и знаки четвёрки
const normal = (): [number[], number] => { const [a, b, cc, d] = pick(TR3), p = pick(PERM), v = [a, b, cc]; return [p.map(i => sgn() * v[i]), d] }

const P = 'Задачи на проценты', M = 'Задачи на смеси и сплавы', W = 'Задачи на совместную работу', D = 'Задачи на движение'
const S = 'Статистика: среднее, мода, медиана', PR = 'Теория вероятностей'
const AP = 'Арифметическая прогрессия', GP = 'Геометрическая прогрессия', IG = 'Бесконечно убывающая геометрическая прогрессия'
const V1 = 'Координаты и длина вектора', V2 = 'Действия над векторами', V3 = 'Скалярное произведение. Угол между векторами'
const V4 = 'Коллинеарные и перпендикулярные векторы', C1 = 'Уравнение окружности и прямой', C2 = 'Уравнения сферы и плоскости. Расстояния'

// ---------- Наборы параметров, подобранные «от ответа» ----------
// Смеси: x кг a%, y кг b% и m кг воды дают c%; с m кг d% вместо воды — e%
const MIX2: number[][] = []
for (const a of [10, 20, 30, 40, 50, 60]) for (const b of [10, 20, 30, 40, 50, 60]) if (a !== b)
  for (const d of [20, 40, 50, 60, 70, 80, 90]) for (let x = 1; x <= 8; x++) for (let y = 1; y <= 8; y++) for (let m = 1; m <= 6; m++) {
    const t = x + y + m, s = a * x + b * y
    if (s % t === 0 && (s + d * m) % t === 0 && d !== a && d !== b) MIX2.push([a, b, d, x, y, m, s / t, (s + d * m) / t])
  }
// Два раствора: m1 кг a% и m2 кг b% дают c%
const MIX4: number[][] = []
for (let m1 = 1; m1 <= 9; m1++) for (let m2 = 1; m2 <= 9; m2++) if (m1 !== m2)
  for (let a = 5; a <= 60; a += 5) for (let b = 5; b <= 60; b += 5) if (a !== b && (m1 * a + m2 * b) % (m1 + m2) === 0) MIX4.push([m1, a, m2, b, (m1 * a + m2 * b) / (m1 + m2)])
// Совместная работа: a < b, ab/(a+b) — целое
const JOB1: number[][] = []
for (let a = 2; a <= 40; a++) for (let b = a + 1; b <= 60; b++) if ((a * b) % (a + b) === 0 && b - a <= 20 && a * b >= 2 * (a + b)) JOB1.push([a, b, (a * b) / (a + b)])
// Две машинистки: остаток работы второй — целое или половина
const JOB2: number[][] = []
for (let a = 3; a <= 20; a++) for (let b = 3; b <= 20; b++) if (a !== b) for (let k = 1; k <= 6; k++) {
  const r = b - k - (k * b) / a
  if (r > 0 && Number.isInteger(2 * r)) JOB2.push([a, b, k, r])
}
// Три бригады попарно: производительности p1, p2, p3
const JOB4: number[][] = []
for (let p1 = 1; p1 <= 6; p1++) for (let p2 = 1; p2 <= 6; p2++) for (let p3 = 1; p3 <= 6; p3++) {
  const w = [p1 + p2, p2 + p3, p1 + p3, p1 + p2 + p3].reduce(lcm)
  if (w <= 60) JOB4.push([w / (p1 + p2), w / (p2 + p3), w / (p1 + p3), w / (p1 + p2 + p3)])
}
// Катер: скорость v, течение u, путь S кратен v + u и v - u
const BOAT: number[][] = []
for (let v = 8; v <= 30; v++) for (let u = 1; u <= 5; u++) { const l = lcm(v + u, v - u); for (let k = 1; k * l <= 200; k++) if (k * l >= 20) BOAT.push([v, u, k * l]) }
// Два автомобиля: S/x - S/(x + d) = t
const CARS: number[][] = []
for (let v = 20; v <= 100; v += 5) for (const d of [5, 10, 15, 20, 25, 30]) for (const t of [0.5, 1, 1.5, 2, 2.5, 3]) {
  const s = (t * v * (v + d)) / d
  if (Number.isInteger(s) && s >= 40 && s <= 800) CARS.push([v, d, t, s])
}
// Сумма бесконечно убывающей прогрессии: q = p/r, b1, b2, b3, S — целые
const QS: [number, number][] = [[1, 2], [-1, 2], [1, 3], [-1, 3], [2, 3], [-2, 3], [1, 4], [3, 4], [-1, 4], [1, 5], [2, 5]]
const IGP1: number[][] = []
for (const [p, r] of QS) for (let b = 1; b <= 150; b++) if ((b * p) % r === 0 && (b * p * p) % (r * r) === 0 && (b * r) % (r - p) === 0) IGP1.push([b, p, r])
const IGP3: number[][] = []
for (const [p, r] of QS) for (let b = 1; b <= 60; b++) { const s = (b * r) / (r - p), s2 = (b * b * r * r) / (r * r - p * p); if (Number.isInteger(s) && Number.isInteger(s2)) IGP3.push([b, p, r, s, s2]) }
// |a ± b| при углах 60° и 120°: p² + q² ± pq — точный квадрат
const EIS: number[][] = []
for (let p = 1; p <= 16; p++) for (let q = 1; q <= 16; q++) for (const s of [1, -1]) {
  const r = Math.sqrt(p * p + q * q + s * p * q)
  if (Number.isInteger(r) && p !== q) { EIS.push([p, q, 60, s, r]); EIS.push([p, q, 120, -s, r]) }
}

const shuffle = <X,>(a: X[]) => { for (let i = a.length - 1; i > 0; i--) { const j = rnd(0, i); [a[i], a[j]] = [a[j], a[i]] } return a }
const ANG = [30, 45, 60, 90, 120, 135, 150]

